#!/usr/bin/env python3
"""Generate the inputs of the non-orthogonal cavity from the environment.

prepare_cavity2d.py            blockMesh, controlDict, schemes, setExprFields
prepare_cavity2d.py --distort  displace the blockMesh points and write the
                               probe locations (after blockMesh)
"""
import json
import re
import math
import os
import sys
from pathlib import Path

CASE = Path(__file__).resolve().parent
HEADER = """FoamFile
{{
    version     2.0;
    format      ascii;
    class       {cls};
    object      {obj};
}}

// Generated by prepare_cavity2d.py.

"""


def env(name, kind=float):
    return kind(os.environ[name])


def write(path, text):
    (CASE / path).write_text(text)


def setup():
    length, cells = env("CAVITY_L"), env("CELLS", int)
    m, n = env("MODE_M", int), env("MODE_N", int)
    k = math.pi * math.hypot(m, n) / length
    c = env("CG")
    freq = c * k / (2 * math.pi)
    nt = env("STEPS_PER_PERIOD", int)
    samples = env("PROBE_SAMPLES_PER_PERIOD", int)
    if nt % samples:
        raise SystemExit("STEPS_PER_PERIOD must be a multiple of PROBE_SAMPLES_PER_PERIOD")
    dt = 1.0 / (freq * nt)
    h = length / cells
    return {
        "L": length, "cells": cells, "h": h, "modeM": m, "modeN": n,
        "k": k, "omega": c * k, "f": freq, "rho": env("RHOG"), "c": c,
        "Pa": env("PA"), "distortion": env("DISTORTION"),
        "laplacian": os.environ["LAPLACIAN"], "stepsPerPeriod": nt,
        "nPeriods": env("N_PERIODS", int), "deltaT": dt,
        "nSteps": nt * env("N_PERIODS", int), "probeStride": nt // samples,
        "courant": c * dt / h, "cellsPerWavelength": 2 * math.pi / k / h,
        "method": os.environ["TIME_METHOD"], "theta": env("THETA"),
        "blockSolver": os.environ["BLOCK_SOLVER"],
        "nonOrthCorrectors": env("NONORTH_CORRECTORS", int),
        "nonOrthMode": os.environ["NONORTH_MODE"],
        "nonOrthTolerance": env("NONORTH_TOLERANCE"),
        "wallLayers": env("WALL_LAYERS", int),
        "transitionFraction": env("TRANSITION_FRACTION"),
    }


def prepare(s):
    length, cells, h = s["L"], s["cells"], s["h"]
    half = 0.5 * h
    write("system/blockMeshDict", HEADER.format(cls="dictionary", obj="blockMeshDict") + f"""
vertices
(
    (0 0 {-half!r}) ({length!r} 0 {-half!r}) ({length!r} {length!r} {-half!r}) (0 {length!r} {-half!r})
    (0 0 {half!r}) ({length!r} 0 {half!r}) ({length!r} {length!r} {half!r}) (0 {length!r} {half!r})
);

blocks ( hex (0 1 2 3 4 5 6 7) ({cells} {cells} 1) simpleGrading (1 1 1) );

boundary
(
    walls
    {{
        type wall;
        faces ( (0 4 7 3) (1 2 6 5) (0 1 5 4) (3 7 6 2) );
    }}
    frontAndBack
    {{
        type empty;
        faces ( (0 3 2 1) (4 5 6 7) );
    }}
);
""")
    write("constant/transportProperties", HEADER.format(cls="dictionary", obj="transportProperties") + f"""
rhol            998.2;
cl              1482;
rhog            {s['rho']};
cg              {s['c']};
kg              #eval{{1.0/($rhog*$cg*$cg)}};
kl              #eval{{1.0/($rhol*$cl*$cl)}};

f               {s['f']!r};
radiationAveragePeriods 1;

timeIntegrationMethod {s['method']};
timeIntegrationTheta  {s['theta']};
timeBlockLinearSolver {s['blockSolver']};
acousticDampingRate   0;
nonOrthogonalCorrection {s['nonOrthMode']};
nonOrthogonalTolerance {s['nonOrthTolerance']!r};
""")
    scheme = s["laplacian"]
    write("system/fvSchemes", HEADER.format(cls="dictionary", obj="fvSchemes") + f"""
ddtSchemes {{ default Euler; }}
d2dt2Schemes {{ default Euler; }}
gradSchemes {{ default Gauss linear; }}
divSchemes {{ default none; div(u) Gauss linear; }}
laplacianSchemes {{ default Gauss linear {scheme}; }}
interpolationSchemes {{ default linear; }}
snGradSchemes {{ default {scheme}; }}
""")
    end = s["nSteps"] * s["deltaT"]
    write("system/controlDict", HEADER.format(cls="dictionary", obj="controlDict") + f"""
application     {os.environ['SOLVER']};
startFrom       startTime;
startTime       0;
stopAt          endTime;
endTime         {end!r};
deltaT          {s['deltaT']!r};
writeControl    runTime;
writeInterval   {end!r};
purgeWrite      0;
writeFormat     ascii;
writePrecision  16;
writeCompression off;
timeFormat      general;
timePrecision   12;
runTimeModifiable no;
adjustTimeStep  no;

functions
{{
    cellProbes
    {{
        type            probes;
        libs            (sampling);
        writeControl    timeStep;
        writeInterval   {s['probeStride']};
        writePrecision  16;
        fields          (p pDot U);
        #include        "probeLocations"
    }}
}}
""")
    solution = CASE / "system/fvSolution"
    solution.write_text(re.sub(r"nNonOrthogonalCorrectors\s+\d+;",
                               f"nNonOrthogonalCorrectors {s['nonOrthCorrectors']};",
                               solution.read_text()))
    write("system/setExprFieldsDict", HEADER.format(cls="dictionary", obj="setExprFieldsDict") + f"""
expressions
(
    p
    {{
        field       p;
        expression  #{{ {s['Pa']!r}*cos({s['modeM'] * math.pi / length!r}*pos().x())*cos({s['modeN'] * math.pi / length!r}*pos().y()) #}};
    }}
);
""")
    # Placeholder until the points are displaced (blockMesh reads controlDict).
    write("system/probeLocations", "probeLocations\n(\n);\n")
    write("caseSetup.json", json.dumps(s, indent=2) + "\n")
    print(f"cavity {cells}^2, distortion {s['distortion']}, {scheme}, "
          f"N_lambda {s['cellsPerWavelength']:.1f}, N_T {s['stepsPerPeriod']}, "
          f"Co {s['courant']:.3f}, {s['nSteps']} steps, {s['method']}")


def distort(s):
    path = CASE / "constant/polyMesh/points"
    text = path.read_text()
    head, rest = text.split("(", 1)
    count = int(head.strip().split()[-1])
    body, tail = rest.rsplit(")", 1)
    pts = [tuple(map(float, line.strip("() ").split()))
           for line in body.strip().splitlines() if line.strip()]
    if len(pts) != count:
        raise SystemExit("unexpected points format")
    length, eps = s["L"], s["distortion"]
    a = eps * length / (2 * math.pi)
    h, layers = s["h"], s["wallLayers"]
    ramp = s["transitionFraction"] * length

    def weight(c):
        # Zero within `layers` cells of a wall, then a smoothstep over `ramp`.
        d = min(c, length - c) - layers * h
        if d <= 1e-12 * length:
            return 0.0
        if ramp == 0:
            return 1.0
        r = min(d / ramp, 1.0)
        return r * r * (3 - 2 * r)

    moved = []
    for x, y, z in pts:
        w = min(weight(x), weight(y)) if layers or ramp else 1.0
        xn = x + w * a * math.sin(math.pi * x / length) * math.sin(2 * math.pi * y / length)
        yn = y + w * a * math.sin(math.pi * y / length) * math.sin(2 * math.pi * x / length)
        moved.append((xn, yn, z))
    path.write_text(head + "(\n" + "\n".join(
        f"({x!r} {y!r} {z!r})" for x, y, z in moved) + "\n)" + tail)
    # Probe at the centroid of each (convex) cell, in blockMesh order.
    n = s["cells"]
    grid = [[None] * (n + 1) for _ in range(n + 1)]
    # blockMesh numbers the points of the lower z-plane first, x fastest.
    lower = moved[:(n + 1) ** 2]
    for j in range(n + 1):
        for i in range(n + 1):
            grid[j][i] = lower[j * (n + 1) + i]
    lines = []
    for j in range(n):
        for i in range(n):
            quad = [grid[j][i], grid[j][i + 1], grid[j + 1][i + 1], grid[j + 1][i]]
            cx = sum(q[0] for q in quad) / 4
            cy = sum(q[1] for q in quad) / 4
            lines.append(f"    ({cx!r} {cy!r} 0)")
    write("system/probeLocations", "probeLocations\n(\n" + "\n".join(lines) + "\n);\n")


def main():
    s = setup()
    if "--distort" in sys.argv:
        distort(s)
    else:
        prepare(s)


if __name__ == "__main__":
    main()
